-- 後始末：テストデータだけを、識別子（testuser_ または e2euser_ で始まるユーザー名。LIKE の _ は文字どおりに扱うため ESCAPE を使う）で消す（C-05）。
-- testuser_ は開発・単体のテストのデータ、e2euser_ は E2E のデータ。
-- 実行したあと、残りの件数が 0 になることを確かめる（下の SELECT の結果が 0）。
DELETE FROM sample_users WHERE username LIKE 'testuser!_%' ESCAPE '!' OR username LIKE 'e2euser!_%' ESCAPE '!';

SELECT COUNT(*) AS remaining FROM sample_users WHERE username LIKE 'testuser!_%' ESCAPE '!' OR username LIKE 'e2euser!_%' ESCAPE '!';

-- ロール・会社・部署・利用者のテストデータ（#119）。識別子：社員IDが testuser_ / e2euser_、部署名・会社名が [UNIT_TEST] / [E2E_TEST] で始まる。
-- 外部キーの順に消す：監査ログ（操作者がテストの利用者）→ セッション（#120）→ 割り当て → 利用者 → 部署・会社の設定。初期ロールと権限（roles・role_permissions）は消さない。
DELETE FROM audit_logs WHERE actor_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!');
-- login_attempts は識別子（社員ID・IP）を持たない HMAC のキーのため、ここでは消せない。テスト用DBの作り直し（npm run db:reset:test）で消える。
DELETE FROM sessions WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!');
-- 通知（#124）。user_id の外部キーのため、利用者より先に消す。宛先がテストの利用者のものを消す。
DELETE FROM notifications WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!');
-- 既読位置（#237）。user_id・room_id の外部キーのため、利用者・部屋より先に消す。テストの利用者の行と、テストの部署のチャンネル・テストの利用者の DM の部屋の行。
DELETE FROM read_positions WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'));
-- スレッド（#137）。返信は親の投稿を外部キーで指し（messages.parent_message_id）、スレッドの既読位置は利用者・親の投稿を指すため、どちらもメッセージ・利用者より先に消す。
-- 削除するメッセージの集合は、下の2つの DELETE FROM messages と同じ条件（テストの利用者が送ったもの・テストの部署のチャンネルの部屋のもの・テストの利用者が当事者の DM の部屋のもの）。
-- ① その集合のメッセージを親とする返信は、送った人がテストの利用者でなくても消す（残すと外部キー違反になる）。消えるテスト以外の返信の件数は、黙って消さないよう、削除の前に removed_foreign_replies として出す
SELECT COUNT(*) AS removed_foreign_replies FROM messages r WHERE r.parent_message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'))) AND NOT (r.sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR r.room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR r.room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')));
-- ② その集合のメッセージを親とするスレッドの既読位置（読んだ人がテストの利用者でなくても）と、テストの利用者の既読位置
DELETE FROM thread_read_positions WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR parent_message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')));
-- リアクション（#138）。message_id・user_id の外部キーのため、メッセージ・利用者より先に消す。テストの利用者が付けたもの（付けた先が対象外の投稿でも）と、削除する集合のメッセージ（その返信を含む）に付いたもの（付けた人がテストの利用者でなくても）。
DELETE FROM message_reactions WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'))) OR message_id IN (SELECT id FROM messages WHERE parent_message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'))));
-- 添付（#140）。message_id・thread_parent_id・room_id・uploader_id の外部キーのため、メッセージ・部屋・利用者より先に消す。
-- テストの利用者がアップロードしたもの、テストの部屋のもの、削除する集合のメッセージ（その返信を含む）に結び付いたもの・その返信用のもの。R2 の実体は、テストの手順が手元の保存先から消す。
DELETE FROM message_attachments WHERE uploader_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')) OR message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'))) OR message_id IN (SELECT id FROM messages WHERE parent_message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')))) OR thread_parent_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')));
-- ③ 返信を先に、親を後に消す（親は下の DELETE FROM messages で消える）
DELETE FROM messages WHERE parent_message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')));
-- DM（#136）。テストの利用者が当事者に含まれる会話を、外部キーの順に消す：メッセージ → 当事者（その会話の全員分）→ 会話。部屋は、テストの利用者の投稿を消した後（下）に消す。利用者を消すより前に行う。
DELETE FROM messages WHERE room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'));
DELETE FROM conversation_members WHERE conversation_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'));
-- 会話は、当事者の行を持たず、direct_key（2人の利用者IDを ':' でつないだもの）にテストの利用者のIDを含むものだけを消す（e2e/seeds/dms-cleanup.sql と同じ絞り方）
DELETE FROM conversations WHERE room_id NOT IN (SELECT conversation_id FROM conversation_members) AND EXISTS (SELECT 1 FROM users u WHERE (u.login_id LIKE 'testuser!_%' ESCAPE '!' OR u.login_id LIKE 'e2euser!_%' ESCAPE '!') AND instr(conversations.direct_key, u.id) > 0);
-- メッセージ（#201）。外部キーの順：メッセージ → 参加者 → チャンネル → ルーム。投稿者がテストの利用者、またはテストの部署のチャンネルの部屋のものを消す。
DELETE FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!'));
-- 部署のチャンネルと参加者（#196）。外部キーの順：参加者 → チャンネル → ルーム。ルームは、チャンネルの行を持たなくなった kind='channel' のものだけを消す。
DELETE FROM channel_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR channel_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!'));
DELETE FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!');
DELETE FROM rooms WHERE kind = 'channel' AND id NOT IN (SELECT room_id FROM channels);
-- DM の部屋：会話の行もメッセージも持たない kind='direct' のものだけを消す（テストの利用者の投稿は上で消し済み）
DELETE FROM rooms WHERE kind = 'direct' AND id NOT IN (SELECT room_id FROM conversations) AND id NOT IN (SELECT room_id FROM messages);
DELETE FROM user_role_assignments WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!');
DELETE FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!';
DELETE FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!';
DELETE FROM company_settings WHERE company_name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR company_name LIKE '[E2E!_TEST]%' ESCAPE '!';

-- 残りの件数（すべて 0 になることを確かめる）
SELECT
  (SELECT COUNT(*) FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') AS remaining_users,
  (SELECT COUNT(*) FROM sessions WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')) AS remaining_sessions,
  (SELECT COUNT(*) FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!') AS remaining_departments,
  (SELECT COUNT(*) FROM company_settings WHERE company_name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR company_name LIKE '[E2E!_TEST]%' ESCAPE '!') AS remaining_company_settings,
  (SELECT COUNT(*) FROM conversations WHERE room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'))
    OR (room_id NOT IN (SELECT conversation_id FROM conversation_members) AND EXISTS (SELECT 1 FROM users u WHERE (u.login_id LIKE 'testuser!_%' ESCAPE '!' OR u.login_id LIKE 'e2euser!_%' ESCAPE '!') AND instr(conversations.direct_key, u.id) > 0))) AS remaining_conversations,
  (SELECT COUNT(*) FROM rooms WHERE kind = 'direct' AND id NOT IN (SELECT room_id FROM conversations)) AS remaining_direct_rooms,
  (SELECT COUNT(*) FROM read_positions WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'))) AS remaining_read_positions,
  (SELECT COUNT(*) FROM thread_read_positions WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR parent_message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')))) AS remaining_thread_read_positions,
  (SELECT COUNT(*) FROM message_reactions WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')))) AS remaining_message_reactions,
  (SELECT COUNT(*) FROM message_attachments WHERE uploader_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')) OR message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!'))) OR message_id IN (SELECT id FROM messages WHERE parent_message_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')))) OR thread_parent_id IN (SELECT id FROM messages WHERE sender_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!') OR room_id IN (SELECT room_id FROM channels WHERE department_id IN (SELECT id FROM departments WHERE name LIKE '[UNIT!_TEST]%' ESCAPE '!' OR name LIKE '[E2E!_TEST]%' ESCAPE '!')) OR room_id IN (SELECT conversation_id FROM conversation_members WHERE user_id IN (SELECT id FROM users WHERE login_id LIKE 'testuser!_%' ESCAPE '!' OR login_id LIKE 'e2euser!_%' ESCAPE '!')))) AS remaining_message_attachments;
